-- Seed source-linked editorial summaries without fabricating witness reports.
alter table public.events
 add column editorial_summary text,
 add column source_name text,
 add column source_url text,
 add column source_published_at date,
 add column summary_ai_generated boolean not null default false,
 add constraint events_source_url_https check(source_url is null or source_url ~ '^https://');

insert into public.events(id,title,category,location,status,state,created_at,editorial_summary,source_name,source_url,source_published_at,summary_ai_generated) values
 ('e1000000-0000-4000-8000-000000000001','Downtown convention center discussion returns','Local news','Downtown Sioux Falls','open','visible','2026-10-28 12:00:00-05','Experience Sioux Falls and Forward Sioux Falls are renewing public discussion of a downtown convention center while considering continued use of the existing facility.','Sioux Falls Simplified','https://www.sfsimplified.com/your-week-simplified-oct-28-2026/','2026-10-28',true),
 ('e1000000-0000-4000-8000-000000000002','Residents share data center concerns','Community','Carnegie Town Hall · Sioux Falls','open','visible','2026-10-28 12:00:00-05','Hundreds of residents attended a public meeting at Carnegie Town Hall to discuss data centers and share concerns with city and county officials.','Sioux Falls Simplified','https://www.sfsimplified.com/your-week-simplified-oct-28-2026/','2026-10-28',true),
 ('e1000000-0000-4000-8000-000000000003','Sioux Falls school enrollment drops','Local news','Sioux Falls School District','open','visible','2026-10-28 12:00:00-05','Sioux Falls public school enrollment is down 301 students from last year, a change expected to affect enrollment-based funding.','Sioux Falls Simplified','https://www.sfsimplified.com/your-week-simplified-oct-28-2026/','2026-10-28',true),
 ('e1000000-0000-4000-8000-000000000004','SculptureWalk names new executive director','Community','Downtown Sioux Falls','open','visible','2026-10-28 12:00:00-05','SculptureWalk announced Jana Anderson as executive director as the organization transitions back to independent operation from the Washington Pavilion.','Sioux Falls Simplified','https://www.sfsimplified.com/your-week-simplified-oct-28-2026/','2026-10-28',true),
 ('e1000000-0000-4000-8000-000000000005','Giving Hope celebrates 10 years','Community','Sioux Falls','open','visible','2026-10-28 12:00:00-05','Giving Hope is marking its tenth anniversary with bingo events through November 1. The organization says it has raised $1 million for local children.','Sioux Falls Simplified','https://www.sfsimplified.com/your-week-simplified-oct-28-2026/','2026-10-28',true),
 ('e1000000-0000-4000-8000-000000000006','Residents review downtown viaduct plans','Roads & transit','10th & 11th Streets · Downtown Sioux Falls','open','visible','2026-10-26 12:00:00-05','A public open house on October 27 presented updated options for rebuilding the 10th and 11th Street viaducts. Public comments are being accepted through November 10.','Pigeon605','https://pigeon605.com/see-latest-options-weigh-in-on-downtown-viaduct-reconstruction/','2026-10-26',true),
 ('e1000000-0000-4000-8000-000000000007','Jacobson Plaza expansion opens downtown','Community','Jacobson Plaza · Downtown Sioux Falls','open','visible','2026-10-15 12:00:00-05','The second phase of Jacobson Plaza is open, adding gathering spaces, an overlook, and pedestrian connections among Falls Park, the Levitt Shell, and the Steel District.','Dakota News Now','https://www.dakotanewsnow.com/2026/10/15/jacobson-plaza-phase-2-opens-linking-falls-park-downtown-sioux-falls/','2026-10-15',true)
on conflict(id) do nothing;

create or replace function public.organic_feed_before_commerce() returns jsonb language sql stable security definer set search_path=public as $$
 select coalesce(jsonb_agg(row_data order by (row_data->>'score')::numeric desc nulls last,(row_data->>'latest_report_at')::timestamptz desc nulls last,row_data->>'id'),'[]') from (
  select jsonb_build_object('id',e.id,'title',e.title,'category',e.category,'location',e.location,'status',e.status,'created_at',e.created_at,'editorial_summary',e.editorial_summary,'source_name',e.source_name,'source_url',e.source_url,'source_published_at',e.source_published_at,'summary_ai_generated',e.summary_ai_generated,'reports',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'event_id',r.event_id,'author_id',r.author_id,'display_name',p.display_name,'body',r.body,'observed_at',r.observed_at,'created_at',r.created_at,'assisted',r.assisted,'state',r.state,'evidence',coalesce((select jsonb_agg(jsonb_build_object('id',v.id,'mime',v.mime,'sha256',v.sha256,'received_at',v.received_at,'preview_path',case when v.preview_path is not null then v.id::text else null end)) from evidence v where v.report_id=r.id),'[]')) order by r.created_at) from reports r join profiles p on p.id=r.author_id where r.event_id=e.id and r.state='visible'),'[]'))||assessment(e.id) row_data
  from events e where e.state='visible' and e.merged_into is null order by e.created_at desc limit 200
 ) safe;
$$;

create or replace function public.commerce_event(eid uuid) returns jsonb language sql stable security definer set search_path=public as $$
 select jsonb_build_object('id',e.id,'title',e.title,'category',e.category,'location',e.location,'status',e.status,'created_at',e.created_at,'editorial_summary',e.editorial_summary,'source_name',e.source_name,'source_url',e.source_url,'source_published_at',e.source_published_at,'summary_ai_generated',e.summary_ai_generated,'reports',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'event_id',r.event_id,'author_id',r.author_id,'display_name',p.display_name,'body',r.body,'observed_at',r.observed_at,'created_at',r.created_at,'assisted',r.assisted,'state',r.state,'evidence',coalesce((select jsonb_agg(jsonb_build_object('id',v.id,'mime',v.mime,'sha256',v.sha256,'received_at',v.received_at,'preview_path',case when v.preview_path is not null then v.id::text else null end)) from evidence v where v.report_id=r.id),'[]')) order by r.created_at) from reports r join profiles p on p.id=r.author_id where r.event_id=e.id and r.state='visible'),'[]'))||assessment(e.id) from events e where e.id=eid and e.state='visible' and e.merged_into is null;
$$;
